CREATE TABLE public.project_cost_rates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id),boq_item_id uuid NOT NULL REFERENCES public.project_boq_items(id),material_rate_inr numeric NOT NULL CHECK(material_rate_inr>=0 AND material_rate_inr NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)),is_archived boolean NOT NULL DEFAULT false,created_by uuid DEFAULT auth.uid(),updated_by uuid DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,boq_item_id));
GRANT ALL ON public.project_cost_rates TO service_role;
ALTER TABLE public.project_cost_rates ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.project_cost_rates_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id),boq_item_id uuid REFERENCES public.project_boq_items(id),subcontract_rate_id uuid,field text NOT NULL,old_value jsonb,new_value jsonb,changed_by uuid NOT NULL DEFAULT auth.uid(),changed_at timestamptz NOT NULL DEFAULT now(),is_archived boolean NOT NULL DEFAULT false,created_by uuid DEFAULT auth.uid(),updated_by uuid DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.project_cost_rates_log TO service_role;
ALTER TABLE public.project_cost_rates_log ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.project_cost_rates,public.project_cost_rates_log FROM PUBLIC,anon,authenticated;
ALTER TABLE public.subcontract_rates ADD COLUMN includes_material boolean NOT NULL DEFAULT false;
REVOKE SELECT ON public.subcontract_rates FROM anon,authenticated;
GRANT SELECT(id,project_id,contractor_id,rate_type,boq_item_id,work_description,unit,package_qty,is_active,created_by,updated_by,created_at,updated_at) ON public.subcontract_rates TO authenticated;
CREATE FUNCTION public._cost_require_project(p_project_id uuid,p_boq_item_id uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NULL OR NOT public.can_view_running_bill(auth.uid()) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.projects WHERE id=p_project_id AND NOT coalesce(is_archived,false)) THEN RAISE EXCEPTION 'Project not available'; END IF;
IF p_boq_item_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.project_boq_items b WHERE b.id=p_boq_item_id AND b.boq_id=(SELECT id FROM public.project_boq WHERE project_id=p_project_id ORDER BY version_number DESC,uploaded_at DESC,id DESC LIMIT 1)) THEN RAISE EXCEPTION 'Item is not in the latest project BOQ'; END IF; END $$;
CREATE FUNCTION public._cost_rate_log() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f text; before_row jsonb; after_row jsonb; fields text[]; BEGIN
before_row:=CASE WHEN TG_OP='INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END; after_row:=to_jsonb(NEW); fields:=CASE WHEN TG_TABLE_NAME='project_cost_rates' THEN ARRAY['material_rate_inr'] ELSE ARRAY['rate_type','rate_inr','lump_sum_inr','package_qty','includes_material','is_active'] END;
FOREACH f IN ARRAY fields LOOP IF before_row->f IS DISTINCT FROM after_row->f THEN INSERT INTO public.project_cost_rates_log(project_id,boq_item_id,subcontract_rate_id,field,old_value,new_value,changed_by) VALUES(NEW.project_id,NEW.boq_item_id,CASE WHEN TG_TABLE_NAME='subcontract_rates' THEN NEW.id END,f,before_row->f,after_row->f,coalesce(auth.uid(),NEW.updated_by,NEW.created_by)); END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER project_cost_rates_audit AFTER INSERT OR UPDATE ON public.project_cost_rates FOR EACH ROW EXECUTE FUNCTION public._cost_rate_log();
CREATE TRIGGER subcontract_cost_rates_audit AFTER INSERT OR UPDATE ON public.subcontract_rates FOR EACH ROW EXECUTE FUNCTION public._cost_rate_log();
CREATE FUNCTION public._validate_cost_subcontract(p_contractor_id uuid,p_unit text,p_type text,p_rate numeric,p_lump numeric,p_package numeric) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT EXISTS(SELECT 1 FROM public.labour_contractors WHERE id=p_contractor_id) THEN RAISE EXCEPTION 'Unknown contractor'; END IF;
IF EXISTS(SELECT 1 FROM public.labour_contractors WHERE id=p_contractor_id AND upper(btrim(company_name))='ALTREE') THEN RAISE EXCEPTION 'ALTREE labour is costed through attendance, not piece rates.'; END IF;
IF p_type IS NULL OR p_type NOT IN ('per_unit','lump_sum') THEN RAISE EXCEPTION 'Rate type must be per_unit or lump_sum'; END IF;
IF p_rate IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) OR p_lump IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) OR p_package IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) THEN RAISE EXCEPTION 'Rates must be finite numbers'; END IF;
IF p_type='per_unit' AND coalesce(p_rate,0)<=0 THEN RAISE EXCEPTION 'Per unit needs a rate greater than 0'; END IF;
IF p_type='lump_sum' AND (coalesce(p_lump,0)<=0 OR coalesce(p_package,0)<=0) THEN RAISE EXCEPTION 'Lump sum and package quantity must be greater than 0'; END IF;
IF p_type='lump_sum' AND btrim(p_unit)='%' AND p_package<>100 THEN RAISE EXCEPTION 'Unit %% requires package quantity 100'; END IF; END $$;
CREATE FUNCTION public.set_material_rate(p_project_id uuid,p_boq_item_id uuid,p_rate numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended('project-cost:'||p_project_id::text,0)); PERFORM public._cost_require_project(p_project_id,p_boq_item_id);
IF p_rate IS NULL OR p_rate<0 OR p_rate IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) THEN RAISE EXCEPTION 'Material rate must be a finite number at least 0'; END IF;
INSERT INTO public.project_cost_rates(project_id,boq_item_id,material_rate_inr) VALUES(p_project_id,p_boq_item_id,p_rate) ON CONFLICT(project_id,boq_item_id) DO UPDATE SET material_rate_inr=excluded.material_rate_inr,is_archived=false,updated_by=auth.uid(),updated_at=now(); END $$;
CREATE FUNCTION public.upsert_subcontract_rate(p_project_id uuid,p_boq_item_id uuid,p_contractor_id uuid,p_rate_type text,p_rate numeric DEFAULT NULL,p_lump_sum numeric DEFAULT NULL,p_package_qty numeric DEFAULT NULL,p_includes_material boolean DEFAULT false,p_active boolean DEFAULT true) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.project_boq_items; rid uuid; BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended('project-cost:'||p_project_id::text,0)); PERFORM public._cost_require_project(p_project_id,p_boq_item_id); SELECT * INTO b FROM public.project_boq_items WHERE id=p_boq_item_id;
PERFORM public._validate_cost_subcontract(p_contractor_id,b.unit,p_rate_type,p_rate,p_lump_sum,p_package_qty);
INSERT INTO public.subcontract_rates(project_id,boq_item_id,contractor_id,unit,rate_type,rate_inr,lump_sum_inr,package_qty,includes_material,is_active,created_by,updated_by) VALUES(p_project_id,p_boq_item_id,p_contractor_id,b.unit,p_rate_type,CASE WHEN p_rate_type='per_unit' THEN p_rate END,CASE WHEN p_rate_type='lump_sum' THEN p_lump_sum END,CASE WHEN p_rate_type='lump_sum' THEN p_package_qty END,coalesce(p_includes_material,false),coalesce(p_active,true),auth.uid(),auth.uid()) ON CONFLICT(project_id,contractor_id,boq_item_id) WHERE boq_item_id IS NOT NULL DO UPDATE SET rate_type=excluded.rate_type,unit=excluded.unit,rate_inr=excluded.rate_inr,lump_sum_inr=excluded.lump_sum_inr,package_qty=excluded.package_qty,includes_material=excluded.includes_material,is_active=excluded.is_active,updated_by=auth.uid(),updated_at=now() RETURNING id INTO rid; RETURN rid; END $$;
CREATE FUNCTION public.deactivate_subcontract_rate(p_project_id uuid,p_rate_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended('project-cost:'||p_project_id::text,0)); PERFORM public._cost_require_project(p_project_id); UPDATE public.subcontract_rates SET is_active=false,updated_by=auth.uid(),updated_at=now() WHERE project_id=p_project_id AND id=p_rate_id; IF NOT FOUND THEN RAISE EXCEPTION 'Rate not found in this project'; END IF; END $$;
CREATE FUNCTION public.get_cost_rates(p_project_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; BEGIN
PERFORM public._cost_require_project(p_project_id); SELECT id INTO bid FROM public.project_boq WHERE project_id=p_project_id ORDER BY version_number DESC,uploaded_at DESC,id DESC LIMIT 1;
RETURN jsonb_build_object('boq_id',bid,'items',coalesce((SELECT jsonb_agg(jsonb_build_object('id',b.id,'sno',b.sno,'description',b.item_description,'unit',b.unit,'work_location',b.work_location,'boq_rate',b.boq_rate,'material_rate',r.material_rate_inr,'missing_material_rate',r.id IS NULL AND (EXISTS(SELECT 1 FROM public.site_report_quantities q JOIN public.daily_measurements d ON d.id=q.report_id WHERE q.boq_item_id=b.id AND q.today_qty>0 AND NOT d.is_archived AND d.trade='daily_site_report' AND d.report_status='submitted') OR EXISTS(SELECT 1 FROM public.factory_report_quantities q JOIN public.factory_daily_reports d ON d.id=q.report_id WHERE q.boq_item_id=b.id AND q.today_qty>0 AND NOT q.is_archived AND NOT d.is_archived AND d.status='submitted')),'subcontracts',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'contractor_id',s.contractor_id,'contractor',c.company_name,'rate_type',s.rate_type,'rate',s.rate_inr,'lump_sum',s.lump_sum_inr,'package_qty',s.package_qty,'effective_rate',public.subcontract_effective_rate(s.rate_type,s.rate_inr,s.lump_sum_inr,s.package_qty),'includes_material',s.includes_material,'active',s.is_active) ORDER BY c.company_name) FROM public.subcontract_rates s JOIN public.labour_contractors c ON c.id=s.contractor_id WHERE s.project_id=p_project_id AND s.boq_item_id=b.id),'[]'::jsonb)) ORDER BY b.sno,b.id) FROM public.project_boq_items b LEFT JOIN public.project_cost_rates r ON r.project_id=p_project_id AND r.boq_item_id=b.id AND NOT r.is_archived WHERE b.boq_id=bid),'[]'::jsonb),'contractors',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',company_name) ORDER BY company_name) FROM public.labour_contractors WHERE status='active' AND upper(btrim(company_name))<>'ALTREE'),'[]'::jsonb)); END $$;
CREATE FUNCTION public.validate_cost_rates_upload(p_project_id uuid,p_rows jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE e jsonb; b public.project_boq_items; bid uuid; cid uuid; rate numeric; lump numeric; pkg numeric; material numeric; typ text; inc boolean; key text; seen text[]:=ARRAY[]::text[]; materials jsonb:='{}'; errors jsonb:='[]'; prepared jsonb:='[]'; n integer:=1; BEGIN
PERFORM public._cost_require_project(p_project_id); SELECT id INTO bid FROM public.project_boq WHERE project_id=p_project_id ORDER BY version_number DESC,uploaded_at DESC,id DESC LIMIT 1;
IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rows)>5000 THEN RAISE EXCEPTION 'Upload needs at most 5000 rows'; END IF;
FOR e IN SELECT value FROM jsonb_array_elements(p_rows) LOOP n:=n+1; BEGIN
IF coalesce(e->>'sno','') !~ '^\d+(\.0+)?$' THEN RAISE EXCEPTION 'Invalid BOQ code'; END IF;
SELECT * INTO b FROM public.project_boq_items WHERE boq_id=bid AND sno=(e->>'sno')::numeric::integer; IF b.id IS NULL THEN RAISE EXCEPTION 'Unknown BOQ code in latest version'; END IF;
IF coalesce(e->>'description','')<>b.item_description OR coalesce(e->>'unit','')<>b.unit OR lower(coalesce(e->>'work_location',''))<>b.work_location THEN RAISE EXCEPTION 'Description, unit and work location must match the BOQ'; END IF;
material:=nullif(btrim(e->>'material_rate'),'')::numeric;
IF material IS NOT NULL AND (material<0 OR material IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)) THEN RAISE EXCEPTION 'Material rate must be at least 0 and finite'; END IF;
IF material IS NOT NULL AND materials ? b.id::text AND (materials->>b.id::text)::numeric<>material THEN RAISE EXCEPTION 'Conflicting material rates for the same BOQ item'; END IF;
IF material IS NOT NULL THEN materials:=materials||jsonb_build_object(b.id::text,material); END IF;
cid:=NULL; typ:=NULL; rate:=NULL; lump:=NULL; pkg:=NULL; inc:=false;
IF nullif(btrim(e->>'contractor'),'') IS NOT NULL THEN
SELECT id INTO cid FROM public.labour_contractors WHERE lower(btrim(company_name))=lower(btrim(e->>'contractor')) ORDER BY (status='active') DESC,created_at LIMIT 1;
typ:=e->>'rate_type'; rate:=nullif(btrim(e->>'rate'),'')::numeric; lump:=nullif(btrim(e->>'lump_sum'),'')::numeric; pkg:=nullif(btrim(e->>'package_qty'),'')::numeric;
IF lower(coalesce(e->>'includes_material','false')) NOT IN ('true','false','yes','no','1','0','') THEN RAISE EXCEPTION 'Includes material must be true or false'; END IF;
inc:=lower(coalesce(e->>'includes_material','false')) IN ('true','yes','1'); PERFORM public._validate_cost_subcontract(cid,b.unit,typ,rate,lump,pkg);
key:=b.id::text||':'||cid::text; IF key=ANY(seen) THEN RAISE EXCEPTION 'Duplicate contractor and BOQ item'; END IF; seen:=array_append(seen,key);
ELSIF nullif(btrim(e->>'rate_type'),'') IS NOT NULL OR nullif(btrim(e->>'rate'),'') IS NOT NULL OR nullif(btrim(e->>'lump_sum'),'') IS NOT NULL OR nullif(btrim(e->>'package_qty'),'') IS NOT NULL THEN RAISE EXCEPTION 'Contractor is required for a subcontract rate'; END IF;
IF material IS NULL AND cid IS NULL THEN RAISE EXCEPTION 'Enter a material rate or a contractor rate'; END IF;
prepared:=prepared||jsonb_build_object('boq_item_id',b.id,'material_rate',material,'contractor_id',cid,'rate_type',typ,'rate',rate,'lump_sum',lump,'package_qty',pkg,'includes_material',inc);
EXCEPTION WHEN OTHERS THEN errors:=errors||jsonb_build_object('row',coalesce(e->>'excel_row',n::text),'reason',SQLERRM); END; END LOOP;
RETURN jsonb_build_object('boq_id',bid,'errors',errors,'prepared',prepared,'row_count',jsonb_array_length(p_rows)); END $$;
CREATE FUNCTION public.apply_cost_rates_upload(p_project_id uuid,p_boq_id uuid,p_rows jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v jsonb; e jsonb; BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended('project-cost:'||p_project_id::text,0)); v:=public.validate_cost_rates_upload(p_project_id,p_rows);
IF (v->>'boq_id')::uuid IS DISTINCT FROM p_boq_id THEN RAISE EXCEPTION 'BOQ changed. Run the dry run again.'; END IF;
IF jsonb_array_length(v->'errors')>0 THEN RAISE EXCEPTION 'Upload has rejected rows. Nothing applied.'; END IF;
FOR e IN SELECT value FROM jsonb_array_elements(v->'prepared') LOOP IF e->>'material_rate' IS NOT NULL THEN PERFORM public.set_material_rate(p_project_id,(e->>'boq_item_id')::uuid,(e->>'material_rate')::numeric); END IF;
IF e->>'contractor_id' IS NOT NULL THEN PERFORM public.upsert_subcontract_rate(p_project_id,(e->>'boq_item_id')::uuid,(e->>'contractor_id')::uuid,e->>'rate_type',(e->>'rate')::numeric,(e->>'lump_sum')::numeric,(e->>'package_qty')::numeric,(e->>'includes_material')::boolean,true); END IF; END LOOP;
RETURN jsonb_build_object('applied',jsonb_array_length(v->'prepared')); END $$;
DO $patch$ DECLARE d text; a text:='IF NOT public.can_read_subcontract_rates(auth.uid(), p_project_id)'; BEGIN d:=pg_get_functiondef('public.get_subcontract_rates(uuid)'::regprocedure); IF position(a IN d)=0 THEN RAISE EXCEPTION 'Subcontract reader anchor missing'; END IF; EXECUTE replace(d,a,'IF auth.uid() IS NULL OR NOT public.can_view_running_bill(auth.uid())'); END $patch$;
DO $grants$ DECLARE r record; BEGIN FOR r IN SELECT p.oid::regprocedure signature,p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('_cost_require_project','_cost_rate_log','_validate_cost_subcontract','get_cost_rates','set_material_rate','upsert_subcontract_rate','deactivate_subcontract_rate','validate_cost_rates_upload','apply_cost_rates_upload') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',r.signature); IF left(r.proname,1)<>'_' THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',r.signature); END IF; END LOOP; END $grants$;